      _angular_core__WEBPACK_IMPORTED_MODULE_2__["ɵɵelementStart"](467, "li");
      _angular_core__WEBPACK_IMPORTED_MODULE_2__["ɵɵtext"](468, " No money is asked by Coforge from job applicants or contractors. ");
      _angular_core__WEBPACK_IMPORTED_MODULE_2__["ɵɵelementEnd"]();
      _angular_core__WEBPACK_IMPORTED_MODULE_2__["ɵɵelementStart"](469, "li");
      _angular_core__WEBPACK_IMPORTED_MODULE_2__["ɵɵtext"](470, " Coforge always uses its name on the letterhead for recruitment documentation, such as application forms, terms, and conditions of employment or visa forms. ");
