class UploadResumeComponent {
  constructor(activatedRoute, router, appService, el, dialog) {
    this.activatedRoute = activatedRoute;
    this.router = router;
    this.appService = appService;
    this.el = el;
    this.dialog = dialog;
    this.fieldValue = "";
    this.jobRoute = '';
    this.jobsData = "";
    this.loaderhome = true;
    this.isMobileView = false;
    this.clearAll = false;
    this.showRecommendedJobs = false;
    //Intelligent Match
    this.check = true;
    this.isMobileView = window.innerWidth < 992;
  }
  onResize(event) {
    this.isMobileView = window.innerWidth < 992;
  }
  ngOnInit() {
    this.activatedRoute.params.subscribe(params => {
      console.log(params);
      this.fieldValue = params.fieldValue;
      if (this.fieldValue != '') {
        this.loaderhome = false;
      }
    });
  }
  openPopup() {
    this.popUpRef = this.dialog.open(this.filtersPopup, {
      width: '100%',
      height: '100%',
      maxWidth: '100%',
      maxHeight: '100%'
    });
  }
  closePopup() {
    this.popUpRef.close('true');
  }
  clearSideFilter() {
    this.clearAll = true;
    setTimeout(() => {
      this.clearAll = false;
    }, 0);
  }
  refreshJobsOnSearch(e) {
    console.log("Search button hit");
  }
  onRecommendeJobsFetch(e) {
    this.showRecommendedJobs = true;
    this.jobsData = e;
    console.log("recommended jobs from app", e);
  }
  resetRecommendedJobsEventHandler(e) {
    this.showRecommendedJobs = !e;
  }
  setJobURL(jobURL) {
    let url = window.location.href;
    url = url.substring(0, url.indexOf('jobslist/')) + 'jobview/' + jobURL;
    // let url = this.router.serializeUrl(this.router.createUrlTree(['jobview/' + jobURL]));
    window.open(url, '_blank');
  }
  setJobsCount(jobCount) {
    this.allJobsCount = jobCount;
  }
  refreshPage() {
    window.location.reload();
  }
  setTalentApplyResult(event) {
    if (event.code == 200) {
      this.appService.toast('success', event.message);
    } else {
      this.appService.toast('error', event.message);
    }
  }
  hideDivById() {
    // Get the div element by its ID
    const divElement = document.getElementById('myDiv');
    this.check = false;
    setTimeout(() => {
      this.check = true;
    }, 0);
    if (divElement) {
      //divElement.style.display = 'none';
      this.showRecommendedJobs = !this.showRecommendedJobs;
    }
  }
}
